  }
  [dir=rtl] select {
    background-position: center left 0.625rem;
  }
}
/**
Textarea
 */
textarea {
  height: 10em;
  resize: vertical;
}

/**
Memorable dates (e.g. date of birth)
 */
.memorable-date {
  display: inline-block;
  margin-top: 0;
}

.memorable-date + .memorable-date {
  margin-left: 1rem;
}

[dir=rtl] .memorable-date + .memorable-date {
  margin-left: auto;
  margin-right: 1rem;
}

/**
Radio/checkbox inputs
 */
.radio-item,
.checkbox-item {
  clear: left;
  float: left;
  margin-top: 0.25rem;
  padding-left: 2.125rem;
  position: relative;
}
.radio-item::after,
.checkbox-item::after {
  clear: both;
  content: "";
  display: block;
}

[dir=rtl] .radio-item,
[dir=rtl] .checkbox-item {
  clear: right;
  float: right;
  padding-left: 0;
  padding-right: 2.125rem;
}

.radio-item input,
.checkbox-item input {
  cursor: pointer;
  height: 2.75rem;
  left: -0.625rem;
  margin: 0;
  opacity: 0;
  position: absolute;
  top: -0.125rem;
  width: 2.75rem;
  z-index: 1;
}

[dir=rtl] .radio-item input,
[dir=rtl] .checkbox-item input {
  left: auto;
  right: -0.625rem;
}

.radio-item label,
.checkbox-item label {
  cursor: pointer;
  display: inline-block;
  margin-bottom: 0;
  margin-top: -0.125rem;
  padding: 0.6875rem 0.9375rem 0.625rem 0.0625rem;
  touch-action: manipulation;
}
.radio-item label::before, .radio-item label::after,
.checkbox-item label::before,
.checkbox-item label::after {
  content: "";
  position: absolute;
}
.radio-item label::before,
.checkbox-item label::before {
  background: transparent;
  border: 2px solid;
  height: 1.5rem;
  left: 0;
  top: 0.5rem;
  width: 1.5rem;
}

[dir=rtl] .radio-item label,
[dir=rtl] .checkbox-item label {
  padding: 0.6875rem 0.0625rem 0.625rem 0.9375rem;
}
[dir=rtl] .radio-item label::before,
[dir=rtl] .checkbox-item label::before {
  left: auto;
  right: 0;
}

.radio-item label::before, .radio-item label::after {
  border-radius: 50%;
}
.radio-item label::after {
  background: currentColor;
  border: 5px solid;
  height: 0;
  left: 0.4375rem;
  opacity: 0;
  top: 0.9375rem;
  width: 0;
}

[dir=rtl] .radio-item label::after {
  left: auto;
  right: 0.4375rem;
}

.checkbox-item label::after {
  background: transparent;
  border: solid;
  border-top-color: transparent;
  border-width: 0 0 3px 3px;
  height: 0.40625rem;
  left: 0.375rem;
  opacity: 0;
  top: 0.9375rem;
  transform: rotate(-45deg);
  width: 0.75rem;
}

[dir=rtl] .checkbox-item label::after {
  left: auto;
  right: 0.375rem;
}

.checkbox-group--cluster .checkbox-item {
  clear: none;
  margin-right: 0.75rem;
}

.radio-item:hover input:not(:disabled) + label::before,
.checkbox-item:hover input:not(:disabled) + label::before {
