}

/*------------------------------------*\
    #Disclosure widget
\*------------------------------------*/
.no-js [data-toggle=true] {
  display: none;
}
.no-js [data-toggle=true] + * {
  display: initial;
}

[data-toggle=true] {
  font-size: 0.9375rem;
  line-height: 1.5;
  align-items: center;
  display: inline-flex;
  font-weight: bold;
}
[data-toggle=true]::after {
  block-size: 0.4375rem;
  border-color: black;
  border-style: solid;
  border-width: 0 0.125rem 0.125rem 0;
  content: "";
  inline-size: 0.4375rem;
  margin-block-start: -0.1875rem;
  margin-inline-end: 0.1875rem;
  margin-inline-start: 0.75rem;
  transform: rotate(45deg);
}
[data-toggle=true]:hover {
  box-shadow: 0 0 4px 2px rgba(84, 84, 84, 0.25);
}
[data-toggle=true]:focus {
  background-color: #f9dc4a;
  border-color: #000;
  box-shadow: none;
}

[data-toggle=true][aria-expanded=false] + * {
  display: none;
}

[data-toggle=true][aria-expanded=true]::after {
  margin-block-start: 0.25rem;
  scale: -1;
}
[data-toggle=true][aria-expanded=true] + * {
  display: block;
}

